head.script:
// 화면 리사이징

scwin.contnId;
scwin.sIsurCd;
scwin.sSeq;
scwin.sComNm;
scwin.checkYYYY;
scwin.jobType;
scwin.ToDay = new Date();
scwin.gSTRT_YYYY = parseInt(scwin.ToDay.getYear(), 10) - 1;
scwin.gEND_YYYY = parseInt(scwin.ToDay.getYear(), 10) + 8;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
        file_name.hide();
        txb_seq.hide();
        scwin.contnId = $c.frame.path("../").scwin.contnId;
        // alert(contnId);
        if (scwin.contnId === null || scwin.contnId === "undefined" || scwin.contnId.length <= 0) {
            scwin.contnId = "I";
        }
        await scwin.setCode();
        if (scwin.contnId !== "I") {
            scwin.sIsurCd = $c.frame.path("../").gIsurCd;
            scwin.sSeq = $c.frame.path("../").gSeq;
            scwin.sComNm = $c.frame.path("../").gComNm;
            txb_isur_cd.setValue(scwin.sIsurCd);
            txb_isur_cd.setDisabled('true');
            txb_com_abbrv.setValue(scwin.sComNm);
            txb_seq.setValue(scwin.sSeq);
            img_com_srch.hide();

            // 상세데이터
            await scwin.read(scwin.sIsurCd, scwin.sSeq);
        } else {
            btn_delete.hide();

            // 신규화면
            scwin.setFileDataHeader();
            await scwin.setHeader();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF39302.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name inf_find_OnClick
 * @description inf_find 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.inf_find_OnClick = function() {
    try {
        const filenm = file_name.getValue();
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
        file_name.setValue(inf_find.getValue());
        if (inf_find.getValue() === "") {
            file_name.setValue(filenm);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39302.inf_find_OnClick" });
    }
};

/**
 * @method
 * @name btn_lineadd_onclick
 * @description 「파일추가」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_lineadd_onclick = async function() {
    try {
        if (dts_fileList.getRowCount() === 10) {
            await $c.win.alert("더이상 추가하실 수 없습니다.");
            return;
        }
        dts_fileList.insertRow();
        inf_find.open();
        if (inf_find.getValue() !== "") {
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
            file_name.setValue(inf_find.getValue());
        } else {
            dts_fileList.removeRow(dts_fileList.getRowPosition());
        }
        if (!scwin.canUploadFile()) {
            await $c.win.alert('30MB 이하의 파일만 첨부 가능합니다.');
            dts_fileList.removeRow(dts_fileList.getRowPosition());
            return;
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF39302.btn_lineadd_onclick" });
    }
};

/**
 * @method
 * @name btn_linedelete_onclick
 * @description 「파일삭제」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_linedelete_onclick = function() {
    try {
