/**
 * @method
 * @name grd_fileList_OnDblClick
 * @description grd_fileList 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_fileList_OnDblClick = function(row, colid) {
    try {
        if (row === 0) return;
        if (dts_fileList.getRowStatus(dts_fileList.getRowPosition()) === 0) {
            scwin.filedown(dts_fileList.getCellData(row, "ATTACH_SEQ"));
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39302.grd_fileList_OnDblClick" });
    }
};

