 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        let msg = trs_Save.ErrorMsg;
        if (msg === "T") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A001", "특례기업관리 " + scwin.jobType));
            $c.frame.path("../").fn_Search();
            await $c.win.closePopup();
        } else {
            await $c.win.alert($c.stf.getMessageParam("MSG-A002", "특례기업관리 " + scwin.jobType));
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF39302.trs_Save_OnSuccess" });
