};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setHeader
 * @description set Header 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setHeader = async function() {
    const sbmOptions = {
        id : "sbm_dts_Detail",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Detail=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_Detail.insertRow();
    const sbmOptions2 = {
        id : "sbm_dts_List",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name setCode
 * @description 적용년도 목록 List 2018년도 ~ 현재년도 +6
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    let str = "";
    for (let i = 2018; i <= scwin.gEND_YYYY; i++) {
        str += i + ":" + i + ",";
    }
    str = str.substring(0, str.length - 1);
    $c.cm.setColumnProp(grd_Grid, 'SPECL_APPL_YY', 'Data', str);

    //  지식구분 셋팅
    const sbmOptions = {
        id : "sbm_dts_speclApplTpCd",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_speclApplTpCd=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name read
 * @description 상세데이터 불러오기
 * @param {*} isurcd isurcd
 * @param {*} comseq comseq
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.read = async function(isurcd, comseq) {
    const sbmOptions3 = {
        id : "sbm_trs_Read",
        action : "/ExceptionRuleAdm.do",
        ref : "dts_Detail,dts_fileList",
        target : "trs_Read=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    /* useupdate를 false로 지정함. */
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/ExceptionRuleAdm.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
