///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name check
 * @description 저장 시 체크사항
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.check = async function() {
    // 이전에 입력된 회사데이터 가져오기
    await scwin.checkYYYY();
    if (txb_com_abbrv.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "회사명"));
        txb_isur_cd.focus();
        return false;
    }
    if (edt_SubmitDate.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "신청서제출일"));
        edt_SubmitDate.focus();
        return false;
    }
    if (edt_speclDate.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "특례적용일"));
        edt_speclDate.focus();
        return false;
    }
    if (dts_List.getRowCount() <= 0) {
        await $c.win.alert("적용년도를 1개 이상 입력해 주십시요");
        return false;
    }

    // grd_Grid.redraw = true;
    for (let i = 1; i <= dts_List.getRowCount(); i++) {
        if (dts_List.getCellData(i, "SPECL_APPL_YY") === "" || dts_List.getCellData(i, "SPECL_APPL_TP_CD") === "") {
            await $c.win.alert("입력하지 않은 적용년도와 적용구분이 있습니다. 확인해 주십시요. ");
            return false;
        }
    }
    let T;
    for (let k = 1; k <= dts_List.getRowCount(); k++) {
        T = 0;
        for (let s = 1; s <= dts_List.getRowCount(); s++) {
            if (dts_List.getCellData(k, "SPECL_APPL_YY") === dts_List.getCellData(s, "SPECL_APPL_YY")) {
                T++;
                if (T > 1) {
                    await $c.win.alert("동일한 년도가 입력되어 있습니다. 확인해 주십시요");
                    return false;
                }
            }
        }
    }
    let yyyyStr;
    let cnt = 0;
    if (dts_yyyyCnt.getRowCount() > 0) {
        for (let k = 1; k <= dts_yyyyCnt.getRowCount(); k++) {
            T = 0;
            for (let s = 1; s <= dts_List.getRowCount(); s++) {
                if (dts_yyyyCnt.getCellData(k, "SPECL_APPL_YY") === dts_List.getCellData(s, "SPECL_APPL_YY")) {
                    T++;
                    if (T > 0) {
                        cnt++;
                        if (cnt <= 1) {
                            yyyyStr = dts_yyyyCnt.getCellData(k, "SPECL_APPL_YY");
                        } else {
                            yyyyStr += "," + dts_yyyyCnt.getCellData(k, "SPECL_APPL_YY");
                        }
                    }
                }
            }
        }
        if (cnt > 0) {
            await $c.win.alert("해당회사로  " + yyyyStr + " 년도가 이미 입력되어 있습니다. 확인해 주십시요");
            return false;
        }
    }
    if (txb_skilValuGrd.getValue() !== "") {
        if (!await scwin.checkMaxLength1(txb_skilValuGrd, 100, "기술성평가등급")) {
            txb_skilValuGrd.focus();
            return false;
        }
    }
    if (txb_valuInstNm.getValue() !== "" && !await scwin.checkMaxLength1(txb_valuInstNm, 100, "전문평가기관명")) {
        txb_valuInstNm.focus();
        return false;
    }
    if (tarea_contn.getValue() !== "" && !await scwin.checkMaxLength2(tarea_contn, 2000, "비고")) {
        tarea_contn.focus();
        return false;
    }
    return true;
};

