/**
 * @method
 * @name checkMaxLength1
 * @description check Max Length1 처리
 * @param {Object} obj 컴포넌트
 * @param {Number} size size
 * @param {String} lbl lbl
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkMaxLength1 = async function(obj, size, lbl) {
    let overLen = ($c.stf.getStringSize(obj.getValue()) - size);
    if (overLen > 0) {
        await $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name checkMaxLength2
 * @description check Max Length2 처리
 * @param {Object} obj 컴포넌트
 * @param {Number} size size
 * @param {String} lbl lbl
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkMaxLength2 = async function(obj, size, lbl) {
    let overLen = ($c.stf.getStringSize(obj.getText()) - size);
    if (overLen > 0) {
        await $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name autoYYYY
 * @description 신청서제출일 입력시 적용년도가 자동으로 셋팅 된다.
 * @returns {void}
 * @hidden N
 */
scwin.autoYYYY = function() {
    const gSubmitDate = edt_SubmitDate.getValue();
    const gSubmitDateYYYY = gSubmitDate.substr(0, 4);
    let j = 1;
    let gAutoValue;
    if (gSubmitDate !== "" && dts_List.getCellData(1, "SPECL_APPL_TP_CD") === "" && dts_List.getCellData(2, "SPECL_APPL_TP_CD") === "") {
        for (let i = 1; i <= 7; i++) {
            gAutoValue = dts_List.getCellData(i, "SPECL_APPL_YY");
            if (gAutoValue < gSubmitDateYYYY) {

                // ********************************************************************
                // [WebSquare 전환 추가] 원본 소스와 비교 필요
                //
                // ********************************************************************

                /*ORG SRC: dts_List.nameValue(i, "SPECL_APPL_TP_CD") = '9';*/
                X = '9';
            } else if (gAutoValue >= gSubmitDateYYYY && j <= 5) {
                // 5개년도 면제로 적용

                // ********************************************************************
                // [WebSquare 전환 추가] 원본 소스와 비교 필요
                //
                // ********************************************************************

                /*ORG SRC: dts_List.nameValue(i, "SPECL_APPL_TP_CD") = '1';*/
                X = '1';
                j++;
            } else {

                // ********************************************************************
                // [WebSquare 전환 추가] 원본 소스와 비교 필요
                //
                // ********************************************************************

                /*ORG SRC: dts_List.nameValue(i, "SPECL_APPL_TP_CD") = '2';*/
                X = '2';
            }
        }
    }
};

/**
 * @method
 * @name canUploadFile
 * @description FileSizeLimit 30MB
 * @returns {void}
 * @hidden N
 */
scwin.canUploadFile = function() {
    const maxFileSize = 1024 * 1024 * 30; // 30MB
    const mySize = inf_find.FileInfo('size');
    if (mySize < maxFileSize) {
        return true;
    } else {
        return false;
    }
};

